def reference(family, api) -> None:
    """An executable witness, not the oracle or a prescribed action sequence."""
    s = api.inspect()
    do = api.apply
    if family == "migration":
        do("expand")
        if s["old_writers"]:
            do("capture_changes")
        do("backfill")
        do("audit_backfill")
        if not s["healthy"]:
            do("rollback_expansion")
            return
        if s["legacy_readers"]:
            do("install_compatibility")
        do("cutover")
        if s["legacy_readers"]:
            do("drain_legacy_readers")
        do("drop_old_schema")
        if s["old_writers"]:
            do("remove_capture")
        if s["legacy_readers"]:
            do("remove_compatibility")
    elif family == "release":
        do("verify_artifact")
        if not s["capacity"]:
            do("pause_batch_workers")
        do("allocate_green")
        do("warm_green")
        do("probe_health")
        if not s["healthy"]:
            do("discard_green")
            if not s["capacity"]:
                do("resume_workers_after_abort")
            return
        if s["sticky_sessions"]:
            do("drain_sticky_sessions")
        do("switch_traffic")
        do("retire_blue")
        if not s["capacity"]:
            do("resume_workers_after_release")
    elif family == "ingestion":
        do("claim")
        if not s["replayed"]:
            if s["transactional"]:
                do("begin")
                do("apply_transactional")
            else:
                do("apply_direct")
            do("stage_outbox")
            do("commit_transaction" if s["transactional"] else "persist_direct")
            if s["deduplicating_sink"]:
                do("deliver_idempotently")
            else:
                do("check_delivery_receipt")
                do("deliver_once")
        do("acknowledge")
        do("release_lease")
    elif family == "compensation":
        do("check_stock")
        if not s["stock_available"]:
            do("reject_unavailable")
            return
        do("reserve")
        do("authorize")
        if s["prepaid"]:
            do("capture_prepaid")
        do("ship")
        if s["shipping_available"]:
            if not s["prepaid"]:
                do("capture_postpaid")
            do("settle")
        else:
            do("refund" if s["prepaid"] else "void_authorization")
            do("release_reservation")
    else:
        raise ValueError(family)

def run(api):
    return reference('release', api)
